        return [v / m if m > 0 else 0.0 for v in vals]

    nbm, ncos, nch = nz([x[1] for x in raw]), nz([x[2] for x in raw]), nz([x[3] for x in raw])
    scored = []
    for i, (r, bm, cos, ch, bg) in enumerate(raw):
        scored.append([r, 0.50 * nbm[i] + 0.30 * ncos[i] + 0.10 * nch[i] + 0.35 * bg])
    best = {}
    for r, s in scored:
        lab = r.get("answer")
        if s > best.get(lab, 0.0):
            best[lab] = s
    out = []
    for r, s in scored:
        out.append({"id": r["id"], "score": s + 0.12 * best.get(r.get("answer"), 0.0)})
    out.sort(key=lambda x: (-x["score"], x["id"]))
    return out

