def _stem(w):
    for suf in ("ing", "ness", "ed", "es", "s"):
        if len(w) > 4 and w.endswith(suf):
            w = w[:-len(suf)]
            break
    if len(w) > 4 and w.endswith("y"):
        w = w[:-1]
    return SYN.get(w, w)


def toks(text):
    out = []
    for w in re.findall(r"[a-z]+", text.lower()):
        if len(w) < 3 or w in STOP:
            continue
        out.append(_stem(w))
    return out


def rank(query, memory):
    rows = list(memory)
    n = len(rows)
    if n == 0:
        return []
    docs = []
    df = Counter()
    for r in rows:
        c = Counter(toks(r.get("question", "")))
        df.update(c.keys())
        docs.append((r, c))
    idf = {w: math.log((n + 1.0) / (df[w] + 0.5)) + 1.0 for w in df}
    avg = sum(sum(c.values()) for _, c in docs) / max(1.0, float(n))
    q = Counter(toks(query))

    def vec(c):
        v = {w: (1.0 + math.log(f)) * idf.get(w, 1.0) for w, f in c.items()}
        nrm = math.sqrt(sum(x * x for x in v.values())) or 1e-9
        return {w: x / nrm for w, x in v.items()}

    def dot(d, v):
        return sum(x * v.get(w, 0.0) for w, x in d.items())

    def cos(a, b):
        if len(a) > len(b):
            a, b = b, a
        return sum(x * b.get(w, 0.0) for w, x in a.items())

    qv = vec(q)
    rowvecs = [vec(c) for _, c in docs]
    sums = {}
    for (r, c), v in zip(docs, rowvecs):
        lab = r.get("answer", "")
        d = sums.get(lab)
        if d is None:
            d = {}
            sums[lab] = d
        for w, x in v.items():
            d[w] = d.get(w, 0.0) + x
    norms = {lab: (math.sqrt(sum(x * x for x in d.values())) or 1e-9) for lab, d in sums.items()}

    scores = []
    for (r, c), v in zip(docs, rowvecs):
        lab = r.get("answer", "")
        raw_own = dot(sums[lab], v)
        loo_norm = math.sqrt(max(1e-9, norms[lab] ** 2 - 2.0 * raw_own + 1.0))
        own = (raw_own - 1.0) / loo_norm
        other = -1.0
        for lab2, d2 in sums.items():
            if lab2 == lab:
                continue
            s = dot(d2, v) / norms[lab2]
            if s > other:
                other = s
        if other < 0.0:
            other = 0.0
        m = own - other
        if m >= 0.25:
            f = 1.0
        elif m >= 0.0:
            f = 0.8 + 0.8 * m
        elif m >= -0.25:
            f = 0.55 + m
        else:
            f = 0.25
        if own < 0.2:
            f *= 0.85
        size = sum(c.values()) or 1
        bm = 0.0
        for w, tf in q.items():
            fd = c.get(w, 0)
            if fd:
                bm += idf[w] * fd * 2.2 / (fd + 1.2 * (0.25 + 0.75 * size / max(1.0, avg)))
        scores.append([r.get("id"), bm, cos(qv, v), f])
    mb = max([s[1] for s in scores] or [0.0]) or 1.0
    mc = max([s[2] for s in scores] or [0.0]) or 1.0
    out = [{"id": i, "score": (0.65 * bm / mb + 0.35 * ch / mc) * f} for i, bm, ch, f in scores]
    out.sort(key=lambda x: (-x["score"], x["id"]))
    return out

